def herm(matrix: sp.MatrixBase) -> sp.Matrix:
    return sp.expand((matrix + matrix.H) / 2)


def is_zero(matrix) -> bool:
    if isinstance(matrix, dict):
        return sclean(matrix) == {}
    return sp.expand(matrix) == sp.zeros(matrix.rows, matrix.cols)


def cong_inertia(matrix: sp.MatrixBase) -> tuple:
    """EXACT Hermitian congruence inertia in the (n_+, n_-, n_0) b165 order.

    Sylvester's law applied directly: diagonal pivots take a Schur complement; a
    wholly hollow remainder is repaired by the congruence e_i -> e_i + c e_j
    with c in {1, i}, which is always available because a nonzero off-diagonal
    entry has a nonzero real or a nonzero imaginary part.  This instrument is
    GATED against the landed b165 routine (gate B) and is used ONLY where the
    landed charpoly routine is impractical, i.e. the enlarged observable bases.
    """
    A = sp.Matrix(sp.expand(matrix))
    npos = nneg = 0
    while A.rows:
        n = A.rows
        pivot = next((k for k in range(n) if sp.expand(A[k, k]) != 0), None)
        if pivot is None:
            spot = None
            for i in range(n):
                for j in range(i + 1, n):
                    if sp.expand(A[i, j]) != 0:
                        spot = (i, j)
                        break
                if spot is not None:
                    break
            if spot is None:
                return (npos, nneg, n)
            i, j = spot
            value = sp.expand(A[i, j])
            coefficient = sp.Integer(1) if sp.re(value) != 0 else I
            basis = sp.eye(n)
            basis[j, i] = coefficient
            A = sp.expand(basis.H * A * basis)
            continue
        entry = sp.re(sp.expand(A[pivot, pivot]))
        if entry > 0:
            npos += 1
        else:
            nneg += 1
        keep = [k for k in range(n) if k != pivot]
        if not keep:
            return (npos, nneg, 0)
        column = A[keep, [pivot]]
        row = A[[pivot], keep]
        A = sp.expand(A[keep, keep] - (column * row) / A[pivot, pivot])
    return (npos, nneg, 0)


def hermitian_inertia(matrix: sp.MatrixBase, key: str) -> tuple:
    """Inertia with the Hermiticity precondition MEASURED, not assumed.

    b165.real_symmetric_inertia is Descartes-on-charpoly and is only valid on a
    real-rooted (Hermitian) matrix, so every call here is guarded.  Above the
    landed routine's practical size the gated congruence instrument is used and
    the switch is reported.
    """
    if not is_zero(matrix - matrix.H):
        raise AssertionError(f"non-Hermitian matrix handed to inertia: {key}")
    if matrix.rows > 24:
        return tuple(cong_inertia(matrix))
    return tuple(inertia(matrix))


def is_psd(triple) -> bool:
    return triple[1] == 0


def is_pd(triple) -> bool:
    return triple[1] == 0 and triple[2] == 0


# ---------------------------------------------------------------------------
# the committed bench, IMPORTED
# ---------------------------------------------------------------------------
SLICE_C = 1
CARRIER_SIGMA = R(3, 5)
BENCH_SX = R(3, 5)
BENCH_MASS = sp.Integer(1)
ST_GRID = (sp.Integer(0), R(1, 8), R(1, 2), sp.Integer(2), -R(1, 2))
ST_GRID_WIDE = ST_GRID + (R(1, 1000), -R(1, 1000), R(1, 100),
                          -sp.Integer(2), R(3, 4), -R(1, 8))
MASS_GRID = (sp.Integer(3), sp.Integer(1), R(1, 2), R(1, 4), R(1, 5),
             R(1, 10), R(1, 100))
QUENCH_MASSES = (sp.Integer(3), sp.Integer(1), R(1, 10), R(1, 100))
CURVATURE_SAMPLES = 12
BISECTION_STEPS = 7
BISECTION_LO, BISECTION_HI = R(1, 100), sp.Integer(8)
H3_COUPLINGS = (-sp.Integer(1), -sp.Integer(2))
# (tag, cover_t, L_x) -- PHYS_T = cover_t // 2
PRIMARY = (("8x4", 8, 4), ("12x4", 12, 4))
SMALL_T = (("4x4", 4, 4), ("6x4", 6, 4))
TAGS = tuple(tag for tag, _, _ in PRIMARY)
SMALL_TAGS = tuple(tag for tag, _, _ in SMALL_T)
L_X = {"8x4": 4, "12x4": 4, "4x4": 4, "6x4": 4}
PHYS_T = {"8x4": 4, "12x4": 6, "4x4": 2, "6x4": 3}
CORNER_ZERO = {"8x4": False, "12x4": True}      # corner D identically zero
POOL_TWO_LEADS = 5
HANDOFF_ITEMS = 3          # the decision memo; the pool-2 handoff; the specs
RUNTIME_BUDGET_SEC = 150
DEEP_RUNTIME_BUDGET_SEC = 900


class Bench:
    """One (cover extent, L_x, fixed slice) bench of COMMITTED objects."""

    def __init__(self, tag: str, cover_t: int, lx: int, c: int = SLICE_C):
        self.tag = tag
        self.fx = fx = b165.Fixture(cover_t, lx, tag)
        self.c = c
        self.lx = lx
        self.T = fx.PHYS_T
        self.N = fx.PHYS
        self.label = next(l for l in fx.x_trivial if fx.fixed_slice(l) == c)
        self.r = dense(fx.descent(self.label), self.N, self.N)
        self.rows = fx.slice_rows(c, c + 1)
        # THE COMMITTED OBJECT, entry for entry: the REGION PIN on the two links
        # incident to c, then the cover Hodge, then the quotient action.  The
        # free shears (t not in {c-1, c}) stay SYMBOLIC -- that is the record.
        self.pin = b166.region_pin(fx, [c - 1, c])
        self.hodge = b166.ssubs(fx.H_free, self.pin)
        self.Hq = dense(fx.quotient(self.hodge), self.N, self.N)
        self.Kq = dense(
            fx.quotient_connection(fx.edge_d[(0, 0)], self.hodge),
            self.N, self.N)
        self.Q = sp.expand(MASS * self.Hq + self.Kq)
        self.form = self.pair(self.Q)
        self._ginv: dict = {}

    def pair(self, action: sp.MatrixBase, refl: sp.MatrixBase = None,
             rows: tuple = None) -> sp.Matrix:
        """[r Q]_{S,S} = herm(Sel^T r Q Sel), the committed law (H1)."""
        rmat = self.r if refl is None else refl
        use = self.rows if rows is None else rows
        prod = sp.expand(rmat * action)
        n = len(use)
        out = sp.zeros(n, n)
        for a, i in enumerate(use):
            for b, j in enumerate(use):
                out[a, b] = prod[i, j]
        return sp.expand((out + out.H) / 2)

    def carrier(self, sigma=CARRIER_SIGMA, sx=BENCH_SX, mass=BENCH_MASS,
                st=None) -> dict:
        sub = b166.carrier_substitution(
            self.fx, b166.graded_carrier(self.fx, self.c, sigma))
        sub[SX] = sp.sympify(sx)
        sub[MASS] = sp.sympify(mass)
        if st is not None:
            sub[ST] = sp.sympify(st)
        return sub

    def proj(self, t: int) -> sp.Matrix:
        out = sp.zeros(self.N, self.N)
        for x in range(self.lx):
            k = self.lx * (t % self.T) + x
            out[k, k] = 1
        return out

    def covariance(self, action: sp.MatrixBase, key) -> sp.Matrix:
        """G = action^{-1}, cached per (key) so no inverse is taken twice."""
        if key not in self._ginv:
            self._ginv[key] = sp.expand(sp.Matrix(action).inv(method="LU"))
        return self._ginv[key]


# ---------------------------------------------------------------------------
# THE SHIM/TRANSPORT DISCRIMINATOR (Block 168's, applied to every PSD finding)
# ---------------------------------------------------------------------------
def discriminator(build, bench: Bench) -> dict:
    base = build(bench.carrier(st=R(1, 2)))
    return {
        "s_t": not is_zero(base - build(bench.carrier(st=R(1, 8)))),
        "s_x": not is_zero(
            base - build(bench.carrier(sx=R(1, 7), st=R(1, 2)))),
        "m": not is_zero(
            base - build(bench.carrier(mass=sp.Integer(3), st=R(1, 2)))),
        "carrier": not is_zero(
            base - build(bench.carrier(sigma=R(1, 5), st=R(1, 2)))),
        "survives_connection_off": not is_zero(
            build(bench.carrier(sx=sp.Integer(0), st=sp.Integer(0)))),
    }


def carries_transport(flags: dict) -> bool:
    return bool(flags["s_t"] or flags["s_x"])


# ---------------------------------------------------------------------------
# THE OBSERVABLE BASES and the quotient-Gaussian moment machinery (H1-170b)
# ---------------------------------------------------------------------------
def sparse_of(matrix: sp.MatrixBase) -> tuple:
    return tuple((p, q, matrix[p, q])
                 for p in range(matrix.rows) for q in range(matrix.cols)
                 if matrix[p, q] != 0)


def observable_families(bench: Bench, env: dict, enlarged: bool) -> tuple:
    """THE DISCLOSED BASIS -- four bilinear families, each a sum over x.

    O_mass(t) = P_t quotient(H) P_t   the mass-block bilinear
    O_thop(t) = sum_x |t,x><t+1,x|    the temporal hop -- the transport channel
    O_xhop(t) = sum_x |t,x><t,x+1|    the spatial current
    O_plaq(t) = sum_x |t,x><t+1,x+1|  the far-corner/plaquette composite

    THE ENLARGED BASIS adds eight further families and is a PREMISE-CLASS probe
    used ONLY to test whether the m-brackets are basis artefacts.  The four
    disclosed families come FIRST, so the disclosed matrix is exactly the
    LEADING PRINCIPAL SUBMATRIX of the enlarged one.
    """
    lx, T, N = bench.lx, bench.T, bench.N
    Hqn = sp.expand(bench.Hq.subs(env))

    def unit(t, x, t2, x2):
        M = sp.zeros(N, N)
        M[lx * (t % T) + (x % lx), lx * (t2 % T) + (x2 % lx)] = 1
        return M

    def summed(t, dt, dx, weight=lambda x: sp.Integer(1)):
        out = sp.zeros(N, N)
        for x in range(lx):
            out += weight(x) * unit(t, x, t + dt, x + dx)
        return sp.expand(out)

    base = (
        ("mass", lambda t: sp.expand(bench.proj(t) * Hqn * bench.proj(t))),
        ("thop", lambda t: summed(t, 1, 0)),
        ("xhop", lambda t: summed(t, 0, 1)),
        ("plaq", lambda t: summed(t, 1, 1)),
    )
    if not enlarged:
        return base
    return base + (
        ("thop2", lambda t: summed(t, 2, 0)),
        ("aplaq", lambda t: summed(t, 1, -1)),
        ("xhop2", lambda t: summed(t, 0, 2)),
        ("sthop", lambda t: summed(t, 1, 0,
                                   lambda x: sp.Integer((-1) ** x))),
        ("ithop", lambda t: sp.expand(I * summed(t, 1, 0))),
        ("site", lambda t: bench.proj(t)),
        ("phop", lambda t: unit(t, 0, t + 1, 0)),
        ("rhop", lambda t: summed(t + 1, -1, 0)),
    )


def moment_matrices(bench: Bench, env: dict, action: sp.MatrixBase = None,
                    key=None, enlarged: bool = False) -> dict:
    """The quotient-Gaussian moment matrices on the named basis.

    Every entry is assembled from the SPARSE support of the observables:
      connected  M[i,j] = tr(A_i^H G A_j G)
                        = sum conj(A_i[a,b]) A_j[c,d] G[b,c] G[d,a]
      full       M[i,j] = connected + tr(A_i^H G) tr(A_j G)
    so no dense matrix product is ever formed and no float ever appears.
    """
    Q = sp.expand((bench.Q if action is None else action).subs(env))
    ckey = (bench.tag, "committed" if action is None else key,
            tuple(sorted((str(k), str(v)) for k, v in env.items())))
    G = bench.covariance(Q, ckey)
    families = observable_families(bench, env, enlarged)
    times = tuple(range(bench.T // 2 + 1))
    mats, labels = [], []
    for name, fn in families:
        for k in times:
            mats.append(sp.expand(fn(bench.c + k)))
            labels.append(f"{name}+{k}")
    n = len(mats)
    sparse = [sparse_of(M) for M in mats]
    reflected = [sp.expand(bench.r * M.conjugate() * bench.r) for M in mats]
    sparse_theta = [sparse_of(M) for M in reflected]

    def gram(left_sparse):
        # tr(A_i^H G A_j G) = sum conj(A_i[a,b]) A_j[c,d] G[a,c] G[d,b]
        out = sp.zeros(n, n)
        for i in range(n):
            for j in range(n):
                total = sp.Integer(0)
                for a, b, va in left_sparse[i]:
                    for c, d, vb in sparse[j]:
                        total += sp.conjugate(va) * vb * G[a, c] * G[d, b]
                out[i, j] = sp.expand(total)
        return out

    def one_point(left_sparse):
        # tr(A^H G) = sum conj(A[a,b]) G[a,b]
        return [sp.expand(sum((sp.conjugate(v) * G[a, b]
                               for a, b, v in left_sparse[i]), sp.Integer(0)))
                for i in range(n)]

    def trace_ga(index):
        # tr(G A) = sum A[c,d] G[d,c]
        return sp.expand(sum((v * G[d, c] for c, d, v in sparse[index]),
                             sp.Integer(0)))

    conn = gram(sparse)
    one = one_point(sparse)
    tga = [trace_ga(j) for j in range(n)]
    full = sp.Matrix(n, n, lambda i, j: sp.expand(conn[i, j] + one[i] * tga[j]))
    return {"labels": tuple(labels), "connected": conn, "full": full,
            "reflected": gram(sparse_theta), "G": G, "n": n,
            "families": tuple(f[0] for f in families), "times": times}


def family_block(mm: dict, name: str) -> sp.Matrix:
    idx = [k for k, lab in enumerate(mm["labels"]) if lab.startswith(name + "+")]
    return sp.Matrix(len(idx), len(idx),
                     lambda a, b: mm["connected"][idx[a], idx[b]])


def structure_flags(mm: dict, name: str) -> tuple:
    """(Hankel c_{s+t}, Toeplitz c_{|s-t|}) on a single-family sub-block."""
    idx = [k for k, lab in enumerate(mm["labels"]) if lab.startswith(name + "+")]
    conn = mm["connected"]
    hankel = all(sp.expand(conn[idx[a], idx[b]] - conn[idx[c], idx[d]]) == 0
                 for a in range(len(idx)) for b in range(len(idx))
                 for c in range(len(idx)) for d in range(len(idx))
                 if a + b == c + d)
    toeplitz = all(sp.expand(conn[idx[a], idx[b]] - conn[idx[c], idx[d]]) == 0
                   for a in range(len(idx)) for b in range(len(idx))
                   for c in range(len(idx)) for d in range(len(idx))
                   if abs(a - b) == abs(c - d))
    return (hankel, toeplitz)


# ---------------------------------------------------------------------------
# B. the anchors, the convention collision and the baseline wall
# ---------------------------------------------------------------------------
def convention_probe() -> dict:
    """The two landed helpers on IDENTICAL matrices -- MEASURED, not asserted."""
    probes = (sp.diag(1, 1, 1, 1, 0, 0, 0, 0),
              sp.diag(1, 1, 1, 1, -1, -1, -1, -1),
              sp.zeros(3, 3))
    pairs = tuple((tuple(b163.congruence_inertia(p)), tuple(inertia(p)))
                  for p in probes)
    # the congruence instrument this block adds, cross-checked against the
    # landed routine on a deterministic exact battery including hollow and
    # rank-deficient cases
    battery = []
    for seed in range(24):
        size = 2 + seed % 7
        M = sp.zeros(size, size)
        for i in range(size):
            for j in range(i, size):
                value = R((3 * i + 5 * j + seed) % 7 - 3, 1 + (i + j + seed) % 5)
                extra = R((2 * i + 7 * j + 3 * seed) % 5 - 2, 2 + (j + seed) % 3)
                if i == j:
                    M[i, i] = value if seed % 4 else sp.Integer(0)
                else:
                    M[i, j] = value + I * extra
                    M[j, i] = value - I * extra
        battery.append(M)
    battery.append(sp.Matrix([[0, 1], [1, 0]]))
    battery.append(sp.Matrix([[0, I], [-I, 0]]))
    battery.append(sp.zeros(4, 4))
    battery.append(sp.diag(1, 1, 0, 0, -1))
    battery.append(sp.Matrix([[0, 0, 1], [0, 0, 0], [1, 0, 0]]))
    battery.append(sp.diag(R(1, 3), -R(2, 7), 0))
    agree = sum(1 for M in battery
                if tuple(inertia(M)) == tuple(cong_inertia(M)))
    return {"pairs": pairs, "orders_differ": pairs[0][0] != pairs[0][1],
            "landed_psd": pairs[0][0][2] == 0, "here_psd": pairs[0][1][1] == 0,
            "instrument_agree": (agree, len(battery))}


def anchor_probe(benches: dict) -> dict:
    out = {}
    for tag, bench in benches.items():
        landed, _ = b166.region_pairing(
            bench.fx, bench.c, bench.fx.edge_d[(0, 0)], [bench.c - 1, bench.c])
        env = bench.carrier()
        rebuilt = is_zero(sp.expand(bench.form.subs(env))
                          - sp.expand(landed.subs(env)))
        d2 = smul(bench.fx.edge_d[(0, 0)], bench.fx.edge_d[(0, 0)])
        out[tag] = {"bench_is_landed": rebuilt, "d_squared_entries": len(d2),
                    "x_trivial": len(bench.fx.x_trivial),
                    "involutive": len(bench.fx.involutive),
                    "r_squared_one": is_zero(
                        bench.r * bench.r - sp.eye(bench.N))}
    return out


def baseline_probe(benches: dict) -> dict:
    out = {}
    for tag, bench in benches.items():
        lx = bench.lx
        row = {}
        for st in ST_GRID:
            row[st] = hermitian_inertia(
                sp.expand(bench.form.subs(bench.carrier(st=st))),
                f"baseline {tag} {st}")
        moduli = {k: v for k, v in bench.carrier().items() if k is not ST}
        Fs = sp.expand(bench.form.subs(moduli))
        B = sp.expand(Fs[:lx, :lx])
        C = sp.expand(Fs[:lx, lx:])
        D = sp.expand(Fs[lx:, lx:])
        Dsym = sp.expand(bench.form[lx:, lx:])
        out[tag] = {
            "grid": row,
            "b_free_of_st": ST not in free_symbols_of(B),
            "c_linear_in_st": is_zero(C - ST * sp.diff(C, ST)),
            "corner_zero": is_zero(D),
            "corner_diagonal_zero": all(
                sp.expand(Dsym[k, k]) == 0 for k in range(lx)),
            "psd_at_zero": is_psd(row[sp.Integer(0)]),
            "not_psd_off_zero": sum(
                1 for st in ST_GRID if st != 0 and not is_psd(row[st])),
        }
    return out


# ---------------------------------------------------------------------------
# C. V1 -- THE RESTRICTED CONES
# ---------------------------------------------------------------------------
def kernel_basis(mats: list, n: int) -> sp.Matrix:
    if not mats:
        return sp.eye(n)
    stacked = sp.Matrix.vstack(*[sp.expand(m) for m in mats])
    ker = stacked.nullspace()
    return sp.Matrix.hstack(*ker) if ker else sp.zeros(n, 0)


def cone_probe(benches: dict, mm_cache: dict) -> dict:
    out = {}
    for tag, bench in benches.items():
        lx = bench.lx
        env = bench.carrier(st=R(1, 2))
        F = sp.expand(bench.form.subs(env))
        row: dict = {}

        # (a1) THE RECORD-BLIND SUBSPACE, at the LANDED record definition
        record_syms = b166.free_shears(bench.fx, bench.c)
        derivs = [sp.expand(sp.diff(bench.form, s).subs(env))
                  for s in record_syms]
        live = [d for d in derivs if not is_zero(d)]
        X = kernel_basis(live, 2 * lx)
        row["record_size"] = len(record_syms)
        row["record_movers"] = len(live)
        row["dim_w"] = X.cols
        row["ambient"] = 2 * lx
        if X.cols:
            FW = sp.expand(X.H * F * X)
            row["record_cone"] = hermitian_inertia(FW, f"v1a1 {tag}")
            row["record_cone_flags"] = discriminator(
                lambda e, b=bench, Xc=X: sp.expand(
                    Xc.H * sp.expand(b.form.subs(e)) * Xc), bench)
            row["record_cone_is_slice_c"] = bool(
                X.cols == lx and is_zero(X[lx:, :]))
        else:
            row["record_cone"] = None
            row["record_cone_flags"] = None
            row["record_cone_is_slice_c"] = False

        # THE WIDER RECORD, disclosed: every unpinned carrier modulus the form
        # actually depends on, not only the cells the landed helper names.
        wider = tuple(sorted(
            (s for s in free_symbols_of(bench.form)
             if s not in (SX, ST, MASS)), key=str))
        wider_derivs = [sp.expand(sp.diff(bench.form, s).subs(env))
                        for s in wider]
        wider_live = [d for d in wider_derivs if not is_zero(d)]
        row["wider_record_size"] = len(wider)
        row["wider_record_movers"] = len(wider_live)
        row["wider_dim_w"] = kernel_basis(wider_live, 2 * lx).cols

        # (a2) THE SECTOR-DIAGONAL CONE
        Fd = sp.expand(sp.diag(F[:lx, :lx], F[lx:, lx:]))
        row["sector_cone"] = hermitian_inertia(Fd, f"v1a2 {tag}")
        row["sector_cone_flags"] = discriminator(
            lambda e, b=bench, l=lx: sp.expand(sp.diag(
                sp.expand(b.form.subs(e))[:l, :l],
                sp.expand(b.form.subs(e))[l:, l:])), bench)
        row["sector_outgoing_null"] = is_zero(F[lx:, lx:])

        # THE CHECKER'S THIRD CONE: the *-algebra generated by the mass-block
        # bilinears -- its own state, and its own reflection form.
        third = {}
        for mass in (BENCH_MASS, R(1, 10)):
            envm = bench.carrier(mass=mass, st=R(1, 2))
            Hqn = sp.expand(bench.Hq.subs(envm))
            gens = [sp.expand(bench.proj(bench.c + k) * Hqn
                              * bench.proj(bench.c + k))
                    for k in range(bench.T // 2 + 1)]
            products = [sp.expand(g * g) for g in gens]
            algebra = [g for g in gens + products if not is_zero(g)]
            key = (bench.tag, "committed",
                   tuple(sorted((str(k), str(v)) for k, v in envm.items())))
            G = bench.covariance(sp.expand(bench.Q.subs(envm)), key)
            sparse = [sparse_of(A) for A in algebra]
            theta = [sparse_of(sp.expand(bench.r * A.conjugate() * bench.r))
                     for A in algebra]
            n = len(algebra)

            def gram(left, sp_right=sparse, Gm=G, size=n):
                return sp.Matrix(size, size, lambda i, j: sp.expand(sum(
                    (sp.conjugate(va) * vb * Gm[a, c] * Gm[d, b]
                     for a, b, va in left[i] for c, d, vb in sp_right[j]),
                    sp.Integer(0))))

            third[mass] = {
                "dimension": n,
                "state": hermitian_inertia(herm(gram(sparse)),
                                           f"v1c {tag} {mass}"),
                "reflected": hermitian_inertia(herm(gram(theta)),
                                               f"v1cT {tag} {mass}"),
            }
        row["third_cone"] = third
        out[tag] = row
    return out


# ---------------------------------------------------------------------------
# D. V1b -- THE COMPOSITE CONES and THE REFLECTION-SIGN THEOREM
# ---------------------------------------------------------------------------
def composite_probe(benches: dict, deep: bool) -> dict:
    out = {}
    samples = CURVATURE_SAMPLES * (3 if deep else 1)
    for tag, bench in benches.items():
        fx = bench.fx
        row = {}
        d = fx.edge_d[(0, 0)]
        row["d_squared_entries"] = len(smul(d, d))

        # (b2) THE DRESSED CURVATURE COMPOSITE -- the WHOLE class at once, by a
        # fully generic complex symbol on every far-corner hop.
        Fgen, syms = {}, []
        for t in range(fx.COVER_T):
            for x in range(fx.LX):
                re_s = sp.Symbol(f"fr_{t}_{x}", real=True)
                im_s = sp.Symbol(f"fi_{t}_{x}", real=True)
                syms += [re_s, im_s]
                Fgen[(fx.cover_index(t, x), fx.cover_index(t + 1, x + 1))] = (
                    re_s + I * im_s)
        KF = fx.quotient(sadd(smul(bench.hodge, Fgen),
                              smul(sdagger(Fgen), bench.hodge)))
        formF = bench.pair(sp.expand(I * dense(KF, fx.PHYS, fx.PHYS)))
        FF = sp.expand(formF.subs(bench.carrier(st=R(1, 2))))
        row["curvature_symbols"] = len(syms)
        row["curvature_rank"] = b168.real_linear_rank(FF, syms)
        row["curvature_identically_zero"] = is_zero(FF)
        Dblk = sp.expand(FF[bench.lx:, bench.lx:])
        row["curvature_corner_traceless"] = all(
            sp.expand(Dblk[k, k]) == 0 for k in range(bench.lx))
        census = []
        for seed in range(samples):
            sample = {s: R(1 + (7 * k + 3 * seed) % 5, 3 + ((k + seed) % 4))
                      * (-1) ** (k + seed) for k, s in enumerate(syms)}
            census.append(hermitian_inertia(
                sp.expand(FF.subs(sample)), f"v1b2 {tag} {seed}"))
        row["curvature_census"] = (sum(1 for t in census if is_psd(t)),
                                   len(census))
        row["curvature_signatures"] = tuple(sorted(set(census)))

        # (b3) THE REFLECTION-SIGN THEOREM on the COMMITTED action
        rowsm = fx.slice_rows(bench.c - 1)
        rowsp = fx.slice_rows(bench.c + 1)
        K = sp.expand(bench.Q[rowsm, rowsp])
        env = bench.carrier(st=R(1, 2))
        row["two_step_odd"] = is_zero(K.subs({ST: -ST}) + K)
        row["two_step_even"] = is_zero(K.subs({ST: -ST}) - K)
        row["two_step_vanishes"] = is_zero(sp.expand(K.subs(env)))
        if row["two_step_vanishes"]:
            row["two_step_composite"] = None
            row["two_step_square"] = None
            row["anti_positive"] = None
        else:
            comp = herm(sp.expand(K.subs({ST: -ST}).H * K))
            row["two_step_composite"] = hermitian_inertia(
                sp.expand(comp.subs(env)), f"v1b3 {tag}")
            row["two_step_square"] = hermitian_inertia(
                sp.expand(herm(sp.expand(K.H * K)).subs(env)), f"v1b3sq {tag}")
            # THE THEOREM ITSELF, as an identity: Theta(K)^dagger K + K^dagger K
            row["anti_positive"] = is_zero(sp.expand(
                K.subs({ST: -ST}).H * K + K.H * K))
        out[tag] = row
    return out


# ---------------------------------------------------------------------------
# E. V2 -- SMALL T
# ---------------------------------------------------------------------------
def small_t_probe(deep: bool) -> dict:
    grid = ST_GRID_WIDE if not deep else ST_GRID_WIDE + (
        R(1, 3), -R(1, 3), sp.Integer(5), -sp.Integer(5))
    out = {}
    for tag, cover_t, lx in SMALL_T:
        bench = Bench(tag, cover_t, lx)
        fx = bench.fx
        lxx = bench.lx
        D = sp.expand(bench.form[lxx:, lxx:])
        row = {
            "T_phys": bench.T, "PHYS": bench.N,
            "involutive": len(fx.involutive), "x_trivial": len(fx.x_trivial),
            "r_squared_one": is_zero(bench.r * bench.r - sp.eye(bench.N)),
            "d_squared_entries": len(
                smul(fx.edge_d[(0, 0)], fx.edge_d[(0, 0)])),
            "corner_diagonal_zero": all(
                sp.expand(D[k, k]) == 0 for k in range(lxx)),
            "corner": hermitian_inertia(
                herm(sp.expand(D.subs(bench.carrier(st=R(1, 2))))),
                f"v2 corner {tag}"),
        }
        cells = {}
        for st in grid:
            cells[st] = hermitian_inertia(
                sp.expand(bench.form.subs(bench.carrier(st=st))),
                f"v2 {tag} {st}")
        row["grid"] = cells
        row["psd_cells"] = sum(1 for st in grid if is_psd(cells[st]))
        row["cells"] = len(grid)
        row["psd_at_zero"] = is_psd(cells[sp.Integer(0)])
        out[tag] = row
    return out


# ---------------------------------------------------------------------------
# F. V3 -- THE MOMENT / HANKEL TEST, THE DEMOTION, AND THE H3 DISPOSAL
# ---------------------------------------------------------------------------
def disp2_differential(fx, coupling) -> dict:
    """Block 169's H3 object, REBUILT: d_2 = i g_2 S_t^2 on the cover."""
    return {(fx.cover_index(t, x), fx.cover_index(t + 2, x)): I * coupling
            for t in range(fx.COVER_T) for x in range(fx.LX)}


def generic_differential(fx, tag: str) -> dict:
    """A third member of the connection recipe family, fully symbolic."""
    out = {}
    for t in range(fx.COVER_T):
        for x in range(fx.LX):
            re_s = sp.Symbol(f"gr_{tag}_{t}_{x}", real=True)
            im_s = sp.Symbol(f"gi_{tag}_{t}_{x}", real=True)
            out[(fx.cover_index(t, x), fx.cover_index(t + 3, x + 1))] = (
                re_s + I * im_s)
    return out


def moment_probe(benches: dict, deep: bool) -> dict:
    out = {}
    for tag, bench in benches.items():
        fx = bench.fx
        row: dict = {}

        # --- the SYMBOLIC half of the structural fact, and its SCOPE ---------
        HqF = dense(fx.quotient(fx.H_free), fx.PHYS, fx.PHYS)
        KqF = dense(fx.quotient_connection(fx.edge_d[(0, 0)], fx.H_free),
                    fx.PHYS, fx.PHYS)
        QF = sp.expand(MASS * HqF + KqF)
        row["herm_connection_zero"] = is_zero(herm(KqF))
        row["quotient_h_hermitian"] = is_zero(HqF - HqF.H)
        row["herm_q_is_mass_form"] = is_zero(herm(QF) - MASS * HqF)
        env0 = bench.carrier(st=R(1, 2))
        row["herm_q_inertia"] = hermitian_inertia(
            herm(sp.expand(bench.Q.subs(env0))), f"v3 hermQ {tag}")
        gkey = (tag, "committed",
                tuple(sorted((str(k), str(v)) for k, v in env0.items())))
        Gc = bench.covariance(sp.expand(bench.Q.subs(env0)), gkey)
        row["g_not_hermitian"] = not is_zero(Gc - Gc.H)
        # THE DEMOTION, measured: the recipe is anti-Hermitian for ANY d.
        recipe = {}
        for name, diff in (("committed d_1", fx.edge_d[(0, 0)]),
                           ("H3 d_2", disp2_differential(fx, G2)),
                           ("generic d_3", generic_differential(fx, tag))):
            # THE COVER-LEVEL IDENTITY, which is the recipe's own content:
            # (i(H d + d^dagger H))^dagger = -i(d^dagger H + H d) for ANY d.
            cover = sp.expand(I * dense(
                sadd(smul(fx.H_free, diff), smul(sdagger(diff), fx.H_free)),
                fx.SIZE, fx.SIZE))
            term = dense(fx.quotient_connection(diff, fx.H_free),
                         fx.PHYS, fx.PHYS)
            recipe[name] = {
                "cover_anti_hermitian": is_zero(herm(cover)),
                "herm_zero": is_zero(herm(term)),
                "herm_sum_is_mass_form": is_zero(
                    herm(sp.expand(MASS * HqF + term)) - MASS * HqF),
            }
        row["recipe"] = recipe

        # --- the mass grid, BOTH matrices named ------------------------------
        grid = {}
        for m in MASS_GRID:
            mm = moment_matrices(bench, bench.carrier(mass=m, st=R(1, 2)))
            grid[m] = {
                "connected": hermitian_inertia(herm(mm["connected"]),
                                               f"v3 conn {tag} {m}"),
                "full": hermitian_inertia(herm(mm["full"]),
                                          f"v3 full {tag} {m}"),
                "reflected": hermitian_inertia(herm(mm["reflected"]),
                                               f"v3 refl {tag} {m}"),
            }
            if m in (BENCH_MASS, R(1, 10)):
                grid[m]["blocks"] = {
                    name: hermitian_inertia(herm(family_block(mm, name)),
                                            f"v3 blk {tag} {m} {name}")
                    for name in mm["families"]}
                grid[m]["structure"] = {
                    name: structure_flags(mm, name)
                    for name in mm["families"]}
        row["grid"] = grid
        row["dimension"] = moment_matrices(
            bench, bench.carrier(mass=BENCH_MASS, st=R(1, 2)))["n"]

        # --- the CONTROL: connection off ------------------------------------
        control = {}
        for m in (BENCH_MASS, R(1, 100)):
            mm = moment_matrices(bench, bench.carrier(
                mass=m, sx=sp.Integer(0), st=sp.Integer(0)))
            control[m] = hermitian_inertia(herm(mm["connected"]),
                                           f"v3 ctrl {tag} {m}")
        row["control"] = control

        # --- THE CHANNEL SPLIT, with the matrix NAMED at every numeral -------
        split = {}
        for name, sx, st in (("s_x only", BENCH_SX, sp.Integer(0)),
                             ("s_t only", sp.Integer(0), R(1, 2))):
            mm = moment_matrices(bench, bench.carrier(
                mass=R(1, 10), sx=sx, st=st))
            split[name] = {
                "connected": hermitian_inertia(herm(mm["connected"]),
                                               f"v3 split {tag} {name} c"),
                "full": hermitian_inertia(herm(mm["full"]),
                                          f"v3 split {tag} {name} f"),
            }
        row["channel_split"] = split

        # --- THE EXACT BRACKET, by rational bisection ------------------------
        lo, hi = BISECTION_LO, BISECTION_HI
        top = hermitian_inertia(herm(moment_matrices(
            bench, bench.carrier(mass=hi, st=R(1, 2)))["full"]),
            f"v3 hi {tag}")
        row["bracket"] = None
        if is_psd(top):
            for _ in range(BISECTION_STEPS):
                mid = R(lo + hi, 2)
                trip = hermitian_inertia(herm(moment_matrices(
                    bench, bench.carrier(mass=mid, st=R(1, 2)))["full"]),
                    f"v3 bisect {tag} {mid}")
                if is_psd(trip):
                    hi = mid
                else:
                    lo = mid
            row["bracket"] = (lo, hi, sp.expand(hi - lo))

        # --- THE BASIS QUESTION: monotonicity, and the brackets as artefacts --
        enlarged = {}
        for m in (sp.Integer(3), BENCH_MASS):
            envm = bench.carrier(mass=m, st=R(1, 2))
            big = moment_matrices(bench, envm, enlarged=True)
            small = moment_matrices(bench, envm)
            n_small = small["n"]
            enlarged[m] = {
                "n": big["n"],
                "full": hermitian_inertia(herm(big["full"]),
                                          f"v3 big {tag} {m}"),
                "small_full": grid[m]["full"],
                # THE MONOTONICITY THEOREM, mechanically: the disclosed matrix
                # IS the leading principal submatrix of the enlarged one.
                "principal_submatrix": is_zero(sp.expand(
                    big["full"][:n_small, :n_small] - small["full"])),
                "principal_submatrix_connected": is_zero(sp.expand(
                    big["connected"][:n_small, :n_small]
                    - small["connected"])),
            }
        row["enlarged"] = enlarged

        # --- THE SIGN-QUENCHED MEASURE IS THE CONNECTION-OFF CONTROL ---------
        hq_carrier = sp.expand(herm(sp.expand(bench.Q.subs(env0))))
        off_action = sp.expand(bench.Q.subs(bench.carrier(
            mass=BENCH_MASS, sx=sp.Integer(0), st=sp.Integer(0))))
        row["quench_is_control"] = is_zero(
            sp.expand(hq_carrier.inv(method="LU") - off_action.inv(method="LU")))
        quench = {}
        for m in QUENCH_MASSES:
            envm = bench.carrier(mass=m, sx=sp.Integer(0), st=sp.Integer(0))
            mm = moment_matrices(bench, envm)
            quench[m] = hermitian_inertia(herm(mm["connected"]),
                                          f"v3 quench {tag} {m}")
        row["quench"] = quench
        row["quench_psd"] = sum(1 for m in QUENCH_MASSES if is_psd(quench[m]))

        # --- THE BLOCK 169 H3 DISPOSAL, through this block's own instruments --
        h3 = {}
        for g in H3_COUPLINGS:
            d2 = disp2_differential(fx, g)
            dQ = dense(fx.quotient_connection(d2, bench.hodge),
                       fx.PHYS, fx.PHYS)
            QH3 = sp.expand(bench.Q + dQ)
            corner = sp.expand(bench.pair(QH3)[bench.lx:, bench.lx:])
            cell = {
                "herm_delta_zero": is_zero(herm(dQ)),
                "connection_blind": not ({SX, ST}
                                         & set(free_symbols_of(dQ))),
                "corner_diagonal_zero": all(
                    sp.expand(corner[k, k]) == 0 for k in range(bench.lx)),
                "pairing": hermitian_inertia(
                    sp.expand(bench.pair(QH3).subs(env0)), f"h3 {tag} {g}"),
                "pairing_connection_off": hermitian_inertia(
                    sp.expand(bench.pair(QH3).subs(bench.carrier(
                        sx=sp.Integer(0), st=sp.Integer(0)))),
                    f"h3off {tag} {g}"),
            }
            for m in (BENCH_MASS, R(1, 10)):
                mm = moment_matrices(bench, bench.carrier(mass=m, st=R(1, 2)),
                                     action=QH3, key=("h3", g))
                cell[("moment", m)] = hermitian_inertia(
                    herm(mm["full"]), f"h3 mom {tag} {g} {m}")
            h3[g] = cell
        row["h3"] = h3
        out[tag] = row
    return out


# ---------------------------------------------------------------------------
# G. V4 -- THE TWIST CLASS THEOREM; V5 -- THE AXIS AND THE SPATIAL REFLECTION
# ---------------------------------------------------------------------------
def twist_battery(bench: Bench) -> tuple:
    lx, T, N = bench.lx, bench.T, bench.N

    def diag_sign(fn):
        return sp.diag(*[sp.Integer(fn(k // lx, k % lx)) for k in range(N)])

    def shift_x():
        M = sp.zeros(N, N)
        for t in range(T):
            for x in range(lx):
                M[lx * t + x, lx * t + (x + 1) % lx] = 1
        return M

    def shift_t():
        M = sp.zeros(N, N)
        for t in range(T):
            for x in range(lx):
                M[lx * t + x, lx * ((t + 1) % T) + x] = (
                    sp.Integer(-1) if t + 1 == T else sp.Integer(1))
        return M

    eps = diag_sign(lambda t, x: (-1) ** (t + x))
    sx_, st_ = shift_x(), shift_t()
    return (
        ("eps_staggered", eps),
        ("eps_t", diag_sign(lambda t, x: (-1) ** t)),
        ("eps_x", diag_sign(lambda t, x: (-1) ** x)),
        ("shift_x", sx_),
        ("taste_x", sp.expand(eps * sx_)),
        ("shift_t", st_),
        ("taste_t", sp.expand(eps * st_)),
        ("phase_i", sp.expand(I * sp.eye(N))),
    )


def support_components(matrix: sp.MatrixBase) -> int:
    """Connected components of the SUPPORT GRAPH -- the twist class theorem."""
    n = matrix.rows
    parent = list(range(n))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    for i in range(n):
        for j in range(n):
            if i != j and sp.expand(matrix[i, j]) != 0:
                ri, rj = find(i), find(j)
                if ri != rj:
                    parent[ri] = rj
    return len({find(k) for k in range(n)})


def twist_probe(benches: dict) -> dict:
    out = {}
    for tag, bench in benches.items():
        env = bench.carrier(st=R(1, 2))
        Qn = sp.expand(bench.Q.subs(env))
        cells = {}
        for name, U in twist_battery(bench):
            rp = sp.expand(U * bench.r)
            cells[name] = {
                "involutive": is_zero(rp * rp - sp.eye(bench.N)),
                "symmetry": is_zero(sp.expand(U.H * Qn * U) - Qn),
                "inertia": {
                    st: hermitian_inertia(
                        sp.expand(bench.pair(bench.Q, rp).subs(
                            bench.carrier(st=st))), f"v4 {tag} {name} {st}")
                    for st in (sp.Integer(0), R(1, 2))},
            }
        lx, N = bench.lx, bench.N
        eps = sp.diag(*[sp.Integer((-1) ** (k // lx + k % lx))
                        for k in range(N)])
        for cname, transform in (
                ("C", lambda M: sp.expand(eps * M.T * eps)),
                ("K", lambda M: sp.expand(M.conjugate())),
                ("CK", lambda M: sp.expand(eps * M.conjugate() * eps))):
            CQ = transform(bench.Q)
            cells[cname] = {
                "involutive": None,
                "symmetry": is_zero(sp.expand(CQ.subs(env)) - Qn),
                "inertia": {
                    st: hermitian_inertia(
                        sp.expand(bench.pair(CQ).subs(bench.carrier(st=st))),
                        f"v4C {tag} {cname} {st}")
                    for st in (sp.Integer(0), R(1, 2))},
            }
        out[tag] = {
            "cells": cells,
            "count": len(cells),
            "support_components": support_components(Qn),
            "psd_at_half": sum(1 for c in cells.values()
                               if is_psd(c["inertia"][R(1, 2)])),
            # A LEGITIMATE twisted reflection must be BOTH an involution AND a
            # symmetry of the committed action.  The support-graph theorem says
            # no nontrivial diagonal twist can be both; this measures it.
            "legitimate": tuple(name for name, c in cells.items()
                                if c["involutive"] and c["symmetry"]),
        }
    return out


def axis_probe(benches: dict) -> dict:
    out = {}
    for tag, bench in benches.items():
        fx = bench.fx
        square = (fx.PHYS_T == fx.LX)
        nu, a, b, mu = fx.flat_moduli()
        Qflat = sp.expand(dense(
            fx.quotient_action(fx.edge_d[(0, 0)], fx.cover_hodge(nu, a, b, mu),
                               MASS), fx.PHYS, fx.PHYS))
        env = {MASS: BENCH_MASS}
        A = sp.expand(Qflat.subs(env).subs({SX: R(3, 5), ST: R(1, 2)}))
        B = sp.expand(Qflat.subs(env).subs({SX: R(1, 2), ST: R(3, 5)}))
        # THE FIXTURE IS NAMED: power traces to k = n determine the charpoly
        # over a field of characteristic 0, so this comparison is exact.
        def traces(M):
            powers, cur = [], sp.eye(M.rows)
            for _ in range(M.rows):
                cur = sp.expand(cur * M)
                powers.append(sp.expand(sp.trace(cur)))
            return tuple(powers)
        flat_equal = traces(A) == traces(B)
        Ac = sp.expand(bench.Q.subs(bench.carrier(st=R(1, 2))))
        Bc = sp.expand(bench.Q.subs(bench.carrier(sx=R(1, 2), st=R(3, 5))))
        committed_equal = traces(Ac) == traces(Bc)
        report, exchange = [], (False if square else None)
        if square:
            n = fx.PHYS
            P = sp.zeros(n, n)
            for t in range(fx.PHYS_T):
                for x in range(fx.LX):
                    P[fx.LX * t + x, fx.LX * x + t] = 1
            for vname, M in (("A", A), ("A^T", A.T),
                             ("conj(A)", A.conjugate()), ("A^H", A.H)):
                PA = sp.expand(P.T * M * P)
                direct = is_zero(PA - B)
                support_ok = all(
                    (sp.expand(PA[i, j]) == 0) == (sp.expand(B[i, j]) == 0)
                    for i in range(n) for j in range(n))
                modulus_ok = support_ok and all(
                    sp.expand(sp.Abs(PA[i, j]) ** 2
                              - sp.Abs(B[i, j]) ** 2) == 0
                    for i in range(n) for j in range(n))
                repaired = False
                if modulus_ok:
                    dvals, frontier = {0: sp.Integer(1)}, [0]
                    while frontier:
                        i = frontier.pop()
                        for j in range(n):
                            if sp.expand(B[i, j]) == 0 or j in dvals:
                                continue
                            ratio = sp.simplify(PA[i, j] / B[i, j])
                            dvals[j] = sp.simplify(dvals[i] / ratio)
                            frontier.append(j)
                    if len(dvals) == n:
                        Dm = sp.diag(*[dvals[k] for k in range(n)])
                        repaired = all(
                            sp.simplify(sp.Abs(dvals[k]) ** 2 - 1) == 0
                            for k in range(n)) and is_zero(
                                sp.expand(Dm.H * PA * Dm) - B)
                report.append((vname, direct, support_ok, modulus_ok, repaired))
                exchange = exchange or direct or repaired
        # THE PURE SPATIAL REFLECTION, a PREMISE-CLASS object (H1-170f)
        rx = sp.zeros(fx.PHYS, fx.PHYS)
        for t in range(fx.PHYS_T):
            for x in range(fx.LX):
                rx[fx.LX * t + x, fx.LX * t + ((1 - x) % fx.LX)] = 1
        columns = tuple(fx.LX * t + x
                        for t in range(fx.PHYS_T) for x in (0, 1))
        spatial = {st: hermitian_inertia(
            sp.expand(bench.pair(bench.Q, rx, columns).subs(
                bench.carrier(st=st))), f"v5 spatial {tag} {st}")
            for st in ST_GRID}
        out[tag] = {
            "square": square, "phys_shape": (fx.PHYS_T, fx.LX),
            "flat_spectra_equal": flat_equal,
            "committed_spectra_equal": committed_equal,
            "intertwiners": tuple(report), "exchange": exchange,
            "healing_weights": tuple(b168.HEALING_WEIGHTS),
            "ex_entries": tuple(sorted(set(b105.EX))),
            "et_entries": tuple(sorted(set(b105.ET), key=str)),
            "rx_involutive": is_zero(rx * rx - sp.eye(fx.PHYS)),
            "spatial_support": len(columns),
            "spatial": spatial,
            "spatial_psd": sum(1 for st in ST_GRID if is_psd(spatial[st])),
        }
    return out


# ---------------------------------------------------------------------------
# the measurement pass
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    convention: dict
    anchors: dict
    baseline: dict
    cones: dict
    composites: dict
    small_t: dict
    moments: dict
    twists: dict
    axis: dict
    scope: dict
    exact_no_float: bool
    deep: bool


def measure(deep: bool) -> Facts:
    main_head = resolve_ref("origin/main")
    benches = {tag: Bench(tag, ct, lx) for tag, ct, lx in PRIMARY}
    convention = convention_probe()
    anchors = anchor_probe(benches)
    baseline = baseline_probe(benches)
    cones = cone_probe(benches, {})
    composites = composite_probe(benches, deep)
    small_t = small_t_probe(deep)
    moments = moment_probe(benches, deep)
    twists = twist_probe(benches)
    axis = axis_probe(benches)

    def harvest(node):
        if isinstance(node, dict):
            for key, value in node.items():
                harvest(key)
                harvest(value)
        elif isinstance(node, (tuple, list)):
            for value in node:
                harvest(value)
        elif isinstance(node, (sp.Basic, int)) and not isinstance(node, bool):
            record(node)

    for block in (convention, anchors, baseline, cones, composites, small_t,
                  moments, twists, axis):
        harvest(block)
    exact = all(no_float(value) for value in NUMERALS)
    return Facts(main_head, authority_certificate(main_head), convention,
                 anchors, baseline, cones, composites, small_t, moments,
                 twists, axis, scope_certificate(raw_note()), exact, deep)


