CAUTION_KEYS = ("cycle913_caution", "non_supply_never_necessity",
                "never_no_hilbert_space")


def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "lane_conventions_uniform": False,
        "record_cone_carries_transport": False,
        "third_cone_reflection_psd": False,
        "reflection_sign_theorem": True,
        "small_t_rescues": False,
        "complex_measure_general": False,
        "brackets_basis_invariant": False,
        "hankel_structure": False,
        "class_twist_theorem": True,
        "v5_deferred": False,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_convention_uniform":
        # THE BANNER DENIED: the lane asserted to carry ONE inertia convention,
        # which the two-helper comparison on identical matrices forbids
        claims["lane_conventions_uniform"] = True
    elif mutation == "claim_record_cone_carries_transport":
        # THE SHIM VERDICT DENIED: the record-blind cone asserted to carry
        # transport, which the s_t/s_x blindness battery forbids
        claims["record_cone_carries_transport"] = True
    elif mutation == "claim_third_cone_reflection_psd":
        # THE CHECKER'S THIRD CONE MISREAD: its REFLECTION form asserted PSD,
        # which the measured indefiniteness at both sizes forbids
        claims["third_cone_reflection_psd"] = True
    elif mutation == "break_reflection_sign_theorem":
        # THE SIGN THEOREM DENIED: Theta(K)^dagger K asserted NOT to be the
        # negative of K^dagger K, which the s_t-oddness identity forbids
        claims["reflection_sign_theorem"] = False
    elif mutation == "claim_small_t_rescues":
        # SMALL T ASSERTED TO RESCUE: a PSD point claimed at T_phys < 4, which
        # the eleven-point grid at both small extents forbids
        claims["small_t_rescues"] = True
    elif mutation == "claim_complex_measure_general":
        # THE DEMOTED FORMULATION RE-ASSERTED as a statement of the wall, which
        # the H3-verbatim counterexample and the generic-d recipe identity forbid
        claims["complex_measure_general"] = True
    elif mutation == "claim_brackets_invariant":
        # THE BRACKETS ASSERTED BASIS-INVARIANT, which the enlarged basis
        # destroying the 8x4 m = 1 PSD point forbids
        claims["brackets_basis_invariant"] = True
    elif mutation == "claim_hankel_structure":
        # THE STRUCTURAL FINDING DENIED: a Hankel or Toeplitz moment sequence
        # asserted, which the region pin's broken time-translation invariance
        # forbids at every family, mass and size
        claims["hankel_structure"] = True
    elif mutation == "break_class_twist_theorem":
        # THE CLASS THEOREM DENIED: the support graph asserted disconnected, so
        # that a nontrivial diagonal symmetry could exist -- which the measured
        # single component at both sizes forbids
        claims["class_twist_theorem"] = False
    elif mutation == "claim_v5_deferred":
        # THE UPGRADE DENIED: V5 asserted still DEFERRED, which the measured
        # fully hyperbolic spatial form at every s_t forbids
        claims["v5_deferred"] = True
    elif mutation == "drop_time_translation_cost":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "time_translation_cost")
    elif mutation == "drop_cycle913":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in CAUTION_KEYS)
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim")
    return claims


